<template><main class="preview-page"><header><p>{{ t('publicContentAdmin.previewWarning') }}</p><strong>{{ t('publicContentAdmin.revision',{revision}) }}</strong></header><p v-if="loading" aria-live="polite">{{ t('publicContentAdmin.loading') }}</p><p v-if="error" role="alert">{{ t(`publicContentAdmin.errors.${error}`) }}</p><template v-if="!loading&&!error"><nav aria-label="Content document"><button v-for="name in names" :key="name" :aria-current="active===name?'page':undefined" @click="active=name">{{ t(`publicContentAdmin.documents.${name}`) }}</button></nav><article v-html="html" /></template></main></template>
<script setup>import {computed,ref,onMounted,onBeforeUnmount}from'vue';import{useRoute}from'vue-router';import{publicContentAdminApi}from'@/api/publicContentAdmin.js';import{renderSafePublicMarkdown}from'@/utils/public-content-validation.js';import{useI18n}from'@/composables/useI18n';const{t}=useI18n(),route=useRoute(),names=['home','about','terms','privacy'],active=ref('home'),documents=ref({}),revision=ref(0),loading=ref(true),error=ref(''),controller=new AbortController();let robots=null;const html=computed(()=>renderSafePublicMarkdown(documents.value[active.value]??''));onMounted(async()=>{robots=document.createElement('meta');robots.name='robots';robots.content='noindex, nofollow, noarchive';document.head.append(robots);try{const out=await publicContentAdminApi.preview(Number(route.query.revision),{signal:controller.signal});documents.value=out.documents;revision.value=out.revision}catch(e){if(e.name!=='AbortError')error.value=/^[a-z_]+$/.test(e.code)?e.code:'request_failed'}finally{loading.value=false}});onBeforeUnmount(()=>{controller.abort();robots?.remove()})</script>
<style scoped>.preview-page{max-width:960px;margin:auto;padding:24px}.preview-page header{padding:12px;border:2px solid var(--el-color-warning);border-radius:8px}.preview-page nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.preview-page button{min-height:44px}.preview-page article{overflow-wrap:anywhere}@media(max-width:600px){.preview-page{padding:16px}}</style>
